; Main game loop, for the real game and the attract demo (game_mode = 0). One pass every 3 frames: it sets
; frame_countdown to 3 (the raster IRQ counts it down) and waits for zero at the end of the pass.
; A pass:
;   1. check_demo_abort: in the demo, fire or F1 ends the demo.
;   2. In a game: handle_game_keys, pause_debounce and check_pause_fire (while paused, fire on the
;      current player's joystick ends the pause); while pause_state bit 7 is set the rest of the pass is skipped.
;   3. Clears bit 6 of Yamo's and bits 3-6 of the Ninja's actor_energy; blink_player_label (1UP/2UP),
;      flicker_lantern_flames.
;   4. When room_no_enemy_flag is 0: tick_spawn_timers, update_yamo_spawn, update_ninja_spawn.
;   5. Toggles pass_parity (1, 0, 1, 0 ...).
;   6. run_room_frame_handler (per-room logic), check_background_contact (terrain flags of the actors),
;      check_background_touch (lanterns, exits, deadly tiles).
;   7. Copy protection: protection_check_value = prot_key_tick EOR prot_key_tick_pair (actor_play_step_sound
;      checks it).
;   8. check_fight_collisions when room_no_enemies of the room is 0.
;   9. update_high_score, update_actors (input, AI and actor_action_step of each actor),
;      build_actor_sprites, check_actor_knockouts.
; change_room and the fall/restart code reset the stack and jump back here.
main_loop
        lda #$03                        ; one pass = 3 frames
        sta frame_countdown
        jsr check_demo_abort
        lda game_mode                   ; 1 = real game, 0 = attract demo
        beq main_loop_update
        jsr handle_game_keys
        jsr pause_debounce
        jsr check_pause_fire
        lda pause_state                 ; bit 7 = paused
        bpl main_loop_update
        jmp main_loop_wait_frame
; Clear bit 6 of Yamo's energy and bits 3-6 of the Ninja's energy (bit 7, knocked out, stays), so a positive
; Ninja energy is at most 7.
main_loop_update
        lda actor_energy+1
        and #$bf                        ; Yamo energy: clear bit 6
        sta actor_energy+1
        lda actor_energy+2
        and #$87                        ; Ninja energy: clear bits 3-6
        sta actor_energy+2
        jsr blink_player_label
        jsr flicker_lantern_flames
        lda room_no_enemy_flag          ; nonzero: no enemies spawn in this room
        bne main_loop_toggle_phase
        jsr tick_spawn_timers
        jsr update_yamo_spawn
        jsr update_ninja_spawn
; pass_parity alternates 1, 0, 1, 0 on successive passes; room handlers use it to act on every other pass.
main_loop_toggle_phase
        lda pass_parity
        bne main_loop_phase_to_zero
        lda #$01
        sta pass_parity
        bne main_loop_room_logic
main_loop_phase_to_zero
        dec pass_parity
main_loop_room_logic
        jsr run_room_frame_handler
        jsr check_background_contact
        jsr check_background_touch
; Copy protection: the bytes prot_key_tick and prot_key_tick_pair of the protection page must differ.
; The EOR goes to protection_check_value; actor_play_step_sound damages this instruction (and later the stack)
; when it is zero.
main_loop_protection_check
main_loop_prot_key_lo = * + 1
        lda prot_key_tick               ; operand low byte main_loop_prot_key_lo: step_sound_check_protection2 increments it and reads it back
main_loop_prot_pair_lo = * + 1
        eor prot_key_tick_pair          ; operand low byte main_loop_prot_pair_lo: step_sound_check_protection2 increments it
        sta protection_check_value
        ldx room
        lda room_no_enemies,x           ; room flag: 0 = check sprite collisions
        bne main_loop_actors
        jsr check_fight_collisions
main_loop_actors
        jsr update_high_score
        jsr update_actors
        jsr build_actor_sprites
        jsr check_actor_knockouts
; Observed (PAL): a new pass starts every 3 frames, right after frame_update of the third frame (raster about 264-277). A pass that needs more than 3 frames makes that pass longer; the next pass starts at once (seen once in 300 frames of room 7: 4 frames).
main_loop_wait_frame
        lda frame_countdown
        bne main_loop_wait_frame
        jmp main_loop
; Computes the screen tile position of actor X (0 Bruce, 1 Yamo, 2 Ninja) from its position:
;   actor_cell_col,X = (actor_x,X - 12) / 4   (character column)
;   actor_cell_row,X = (actor_y,X - 12) / 16  (tile row of two characters), with actor_y + 4 in room 13
; Called by check_background_touch for each actor. Changes A.
actor_calc_tile_pos
        lda actor_x,x
        sec
        sbc #$0c                        ; left border
        lsr
        lsr
        sta actor_cell_col,x
        lda room
        cmp #$0d                        ; room 13
        bne actor_calc_tile_pos_row
        lda actor_y,x
        clc
        adc #$04
        bne actor_calc_tile_pos_store_row
actor_calc_tile_pos_row
        lda actor_y,x
actor_calc_tile_pos_store_row
        sec
        sbc #$0c
        lsr
        lsr
        lsr
        lsr
        sta actor_cell_row,x
        rts
